import React from 'react';

import { NavLink } from 'react-router-dom';

import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { confirmUserEmailByCode } from '../@services/user.services';

const EmailConfirmPage = ({ code }: { code: string }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [error, setError] = React.useState<Error>();
  const [data, setData] = React.useState<{ success: boolean; message?: string }>({
    success: false,
  });

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      if (!code) throw new Error('Wrong code');
      const r = await confirmUserEmailByCode(code);
      setData(r);
    } catch (e) {
      setError(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;

  return (
    <PohRow>
      <PohCol sm={12}>
        <PageHeader title="Подтверждение e-mail">
          <PohButton icon={IconsEnum.refresh} onClick={load}></PohButton>
        </PageHeader>
        {error && <PohAlert variant={AlertVariant.Danger}>{error.message}</PohAlert>}

        {data && (
          <PohAlert variant={AlertVariant.Success}>
            E-mail адрес успешно подтверждён!{' '}
            {!!data.message && (
              <>
                <br /> <strong>{data.message}</strong>
              </>
            )}
          </PohAlert>
        )}
        <p>
          Для управления вариантами входа в раздел{' '}
          <NavLink to="/profile#invariants">профиля</NavLink>
        </p>
      </PohCol>
    </PohRow>
  );
};

export default EmailConfirmPage;
